SELECT machine_id, CAST(last_issued_position AS TEXT) AS last_issued_position, typeof(last_issued_position) AS position_class, CAST(expired_through AS TEXT) AS expired_through, typeof(expired_through) AS floor_class, CAST(created_at AS TEXT) AS created_at, typeof(created_at) AS created_class, CAST(updated_at AS TEXT) AS updated_at, typeof(updated_at) AS updated_class FROM machine_control_project_progress WHERE machine_id=?;
